# Caso 30 · union-find
# Error: no une 2-3
p = {1: 1, 2: 2, 3: 3}

def find(x):
    while p[x] != x:
        x = p[x]
    return x

def union(a, b):
    p[find(b)] = find(a)

union(1, 2)
print(find(1) == find(3))
